        scale: { type: "string", description: "e.g. 1/4\"=1'-0\", 1\"=20', 1:50." },
        direction: { type: "string", enum: ["toDrawing", "toReal"], description: "Default toDrawing." },
        out_unit: { type: "string", description: "Unit of the answer." }, to_scale: { type: "string", description: "Also show the same drawing at this scale." },
