export const NEXT64 = {
  calc_quilt: "Next step: calc_fabric_yardage for any extra pieces, or open the page link for the drawn layout and a printable cutting list.",
  calc_fabric_yardage: "Next step: open the page link to drag the layout and print the cutting plan; calc_quilt for quilt backing and binding.",
  optimize_cut_list: "Next step: open the page link to edit parts and print each sheet's layout with the cut order.",
  make_jigsaw_puzzle: "Next step: test-cut a small corner first to tune the kerf; open the page link to preview the pieces over your image.",
  convert_drawing_scale: "Next step: open the page link for a printable scale ruler at this scale.",
};

function quilt(a) {
  const unit = a.unit === "cm" ? "cm" : "in", what = ["plan", "size", "backing", "binding", "border"].includes(a.what) ? a.what : "plan";
  const borders = Array.isArray(a.borders) ? a.borders.slice(0, 6).map(Number).filter((x) => Number.isFinite(x) && x > 0) : [];
  const page = `${T}/quilt-calculator/`;
  const W = num(a.width), L = num(a.length);
  if (what === "backing" || what === "binding" || what === "border") {
    if (!(W > 0) || !(L > 0)) return err(`Give the quilt width and length for the ${what}.`);
    const o = { unit, width: W, length: L };
    if (num(a.usable) > 0) o.usable = num(a.usable);
    let r, lines, sc;
    if (what === "backing") {
      r = Q.backing(o); if (!r || !r.ok) return err(errs(r, "Check the sizes."));
      const b = r[r.best];
      lines = [`**Backing for a ${W} × ${L} ${unit} quilt: ${b.yardsText} (${b.metres} m)** — ${b.panels} panel${b.panels > 1 ? "s" : ""} × ${b.panelLength} ${unit}, ${b.direction} seams (need ${r.need.width} × ${r.need.length} ${unit} with ${r.overhang} ${unit} overhang).`];
      const o2 = r[r.best === "vertical" ? "horizontal" : "vertical"]; if (o2) lines.push(`${o2.direction[0].toUpperCase() + o2.direction.slice(1)} seams instead: ${o2.panels} panels, ${o2.yardsText} (${o2.metres} m).`);
      sc = { what, unit, need: r.need, best: r.best, vertical: r.vertical, horizontal: r.horizontal, page: `${T}/quilt-backing-calculator/` };
    } else if (what === "binding") {
      if (num(a.strip_width) > 0) o.stripWidth = num(a.strip_width);
      r = Q.binding(o); if (!r || !r.ok) return err(errs(r, "Check the sizes."));
      lines = [`**Binding: ${r.strips} strips ${Q.frac(r.stripWidth)} ${unit} × width of fabric = ${r.yardsText} (${r.metres} m)** for ${r.length} ${unit} of binding (perimeter ${r.perimeter} + ${r.extra} ${unit}, ${r.join} joins).`];
      if (r.bias) lines.push(`Continuous bias instead: start from a ${r.bias.square} ${unit} square (minimum ${r.bias.squareMin}), ${r.bias.yardsText} (${r.bias.metres} m).`);
      sc = { what, unit, ...r, page: `${T}/quilt-binding-calculator/` };
    } else {
      o.borders = (borders.length ? borders : [4]).map((w) => ({ width: w, style: a.border_style === "mitred" ? "mitred" : "butted" }));
      r = Q.border(o); if (!r || !r.ok) return err(errs(r, "Check the sizes."));
      lines = [`**Borders: ${r.total.yardsText} (${r.total.metres} m) in total**; quilt grows to ${r.finished.width} × ${r.finished.length} ${unit} finished.`,
        ...r.borders.map((b) => `Border ${b.index} (${b.style}, ${b.width} ${unit}): cut ${b.wofStrips} strips ${Q.frac(b.cutWidth)} ${unit} wide; sides ${b.strips[0].length}, top/bottom ${b.strips[2].length} ${unit}; ${b.yardsText}.`)];
      sc = { what, unit, ...r, page: `${T}/quilt-border-calculator/` };
    }
    if (r.warnings && r.warnings.length) lines.push("Note: " + r.warnings.join(" "));
    lines.push("Yardage is rounded up to 1/8 yd; pre-wash shrinkage is not included. Drawn diagram: " + sc.page);
    return ok(lines.join("\n"), sc);
  }
  const o = { unit };
  if (num(a.cols) > 0 && num(a.rows) > 0 && num(a.block) > 0) Object.assign(o, { mode: "blocks", cols: num(a.cols), rows: num(a.rows), block: num(a.block), sashing: num(a.sashing) || 0, frame: num(a.sashing) > 0, borders });
  else if (a.bed) { if (!BEDS.includes(a.bed)) return err("bed must be one of: " + BEDS.join(", ") + "."); Object.assign(o, { mode: "bed", bed: a.bed }); if (num(a.drop) >= 0) o.drop = o.footDrop = num(a.drop); }
  else return err("Give a bed size, or cols, rows and block size (plus optional sashing and borders).");
  if (num(a.usable) > 0) o.usable = num(a.usable);
  if (num(a.strip_width) > 0) o.stripWidth = num(a.strip_width);
  if (a.border_style === "mitred") o.borderStyle = "mitred";
  if (what === "size") {
    const s = Q.size(o); if (!s || !s.ok) return err(errs(s, "Check the inputs."));
    const lines = [`**Finished quilt: ${s.width} × ${s.length} ${unit}**` + (s.mode === "bed" ? ` for a ${s.bed.name} mattress ${s.bed.mattressW} × ${s.bed.mattressL} ${unit} (drop ${s.bed.drop}, pillow tuck ${s.bed.pillow}).` : ` — ${s.cols} × ${s.rows} = ${s.blocks} blocks, centre ${s.inner.width} × ${s.inner.length} ${unit}.`)];
    if (s.warnings && s.warnings.length) lines.push("Note: " + s.warnings.join(" "));
    lines.push("Full plan with cutting list: " + page);
    return ok(lines.join("\n"), { what, ...s, _in: undefined, page });
  }
  const p = Q.plan(o); if (!p || !p.ok) return err(errs(p, "Check the inputs."));
  const s = p.size, lines = [`**Quilt plan: ${s.width} × ${s.length} ${unit} finished**` + (s.mode === "bed" ? ` (${s.bed.name} bed).` : ` (${s.cols} × ${s.rows} blocks of ${s.block} ${unit}).`),
    "| Item | Cut | Buy |", "|---|---|---|", ...p.cutting.map((c) => `| ${c.item} | ${c.cut} | ${c.yardsText} (${c.metres} m) |`)];
  if (p.batting) lines.push(`Batting: ${p.batting.width} × ${p.batting.length} ${unit}.`);
  if (p.warnings && p.warnings.length) lines.push("Note: " + p.warnings.join(" "));
  lines.push("Fabric figures assume one fabric per item, rounded up to 1/8 yd; pieced blocks need their pattern's own yardage. Layout drawing and printable plan: " + page);
  return ok(lines.join("\n"), { what, unit, size: { ...s, _in: undefined }, cutting: p.cutting, batting: p.batting || null, warnings: p.warnings || [], page });
}

function yardage(a) {
  const unit = a.unit === "cm" ? "cm" : "in", width = num(a.width);
  if (!(width > 0)) return err("width (usable fabric width) must be a positive number.");
  if (!Array.isArray(a.pieces) || !a.pieces.length) return err("pieces must be a list like [{\"w\": 20, \"h\": 30, \"qty\": 2, \"label\": \"Panel\"}].");
  const pieces = a.pieces.slice(0, 60).map((p, i) => ({ w: Number(p && p.w), h: Number(p && p.h), qty: Math.max(1, Math.min(500, Math.round(Number(p && p.qty) || 1))), label: str(p && p.label, 40) || `Piece ${i + 1}` }));
  if (!pieces.every((p) => p.w > 0 && p.h > 0)) return err("Every piece needs a positive w and h.");
  const r = F.yardage({ unit, width, pieces, nap: !!a.nap, repeat: num(a.repeat) || 0, sa: num(a.sa) || 0, shrink: num(a.shrink) || 0, extra: num(a.extra) || 0 });
  if (!r || !r.ok) return err(errs(r, "Check the pieces and width."));
  const page = `${T}/fabric-yardage-calculator/`;
  const lines = [`**Buy ${r.yardsText} (${r.metres} m)** of ${width} ${unit} wide fabric for ${r.count} pieces: ${r2(r.exact)} ${unit} used in ${r.shelves} rows, ${r.efficiency}% of the fabric area is pieces.`];
  if (r.buy > r.exact) lines.push(`Includes ${num(a.shrink) || 0}% shrinkage + ${num(a.extra) || 0}% margin (${r2(r.buy)} ${unit}).`);
  if (a.nap || num(a.repeat) > 0) lines.push("Pieces kept upright for the nap / pattern repeat.");
  if (r.warnings && r.warnings.length) lines.push("Note: " + r.warnings.join(" "));
  const sc = { unit, width, exact: r.exact, buy: r.buy, yards: r.yards, yards_text: r.yardsText, metres: r.metres, efficiency: r.efficiency, shelves: r.shelves, count: r.count,
    placements: (r.placements || []).slice(0, 300), warnings: r.warnings || [], page };
  if (a.format === "svg") { const svg = F.svg(r); if (svg.length > OUT_CAP) lines.push("The layout SVG is too big to return inline."); else { lines.push("Cutting layout SVG:", fence("svg", svg)); sc.svg = svg; } }
  lines.push("Shelf layout is a safe upper bound; a hand layout can sometimes save a little. Interactive layout: " + page);
  return ok(lines.join("\n"), sc);
}

function cutList(a) {
  const mode = a.mode === "linear" ? "linear" : "sheet", unit = a.unit === "in" ? "in" : "mm";
  if (!Array.isArray(a.stocks) || !a.stocks.length || !Array.isArray(a.parts) || !a.parts.length) return err("Give stocks and parts lists, e.g. stocks [{\"w\":2440,\"h\":1220}] and parts [{\"w\":600,\"h\":300,\"qty\":4,\"name\":\"Shelf\"}].");
  const n = (v) => Number(v), q = (v) => Math.max(0, Math.min(500, Math.round(Number(v) || 0)));
  const stocks = a.stocks.slice(0, 10).map((s, i) => mode === "linear" ? { len: n(s && s.len), qty: q(s && s.qty), name: str(s && s.name, 30) || undefined } : { w: n(s && s.w), h: n(s && s.h), qty: q(s && s.qty), name: str(s && s.name, 30) || undefined });
  const parts = a.parts.slice(0, 60).map((p, i) => mode === "linear" ? { len: n(p && p.len), qty: Math.max(1, q(p && p.qty)), name: str(p && p.name, 30) || `Part ${i + 1}` }
    : { w: n(p && p.w), h: n(p && p.h), qty: Math.max(1, q(p && p.qty)), name: str(p && p.name, 30) || `Part ${i + 1}`, grain: !!(p && p.grain) });
  const bad = mode === "linear" ? (x) => !(x.len > 0) : (x) => !(x.w > 0 && x.h > 0);
  if (stocks.some(bad) || parts.some(bad)) return err(mode === "linear" ? "Every stock and part needs a positive len." : "Every stock and part needs positive w and h.");
  if (parts.reduce((t, p) => t + p.qty, 0) > 1000) return err("At most 1,000 parts in total.");
  const r = C.optimize({ mode, unit, kerf: num(a.kerf) !== undefined ? num(a.kerf) : unit === "in" ? 0.125 : 3, trim: num(a.trim) || 0, stocks, parts, rotate: a.rotate !== false });
  if (!r || !r.ok) return err(errs(r, "Check the stock and part sizes."));
  const s = r.summary, page = `${T}/cut-list-optimizer/`, u = unit;
  const lines = mode === "linear"
    ? [`**${s.bars} bar${s.bars === 1 ? "" : "s"} needed: ${s.placed}/${s.total} parts placed, ${r2(s.util)}% used, ${r2(s.waste)}% offcut.**`, ...r.bars.slice(0, 30).map((b, i) => `Bar ${i + 1} (${b.name}): ${b.pieces.map((p) => `${p.name} ${p.len}`).join(", ")} — offcut ${r2(b.offcut)} ${u}.`)]
    : [`**${s.sheets} sheet${s.sheets === 1 ? "" : "s"} needed (${Object.entries(s.byStock).map(([k, v]) => `${v} × ${k}`).join(", ") || "none"}): ${s.placed}/${s.total} parts placed, ${r2(s.util)}% used, ${r2(s.waste)}% waste**, ${Math.round(s.cutLength)} ${u} of cuts. Kerf ${r.kerf} ${u}.`,
      ...r.sheets.slice(0, 20).map((sh, i) => `Sheet ${i + 1} (${sh.name}): ${sh.parts.length} parts, ${r2(sh.util)}% used.`)];
  if (r.unplaced && r.unplaced.length) lines.push("Not placed: " + r.unplaced.slice(0, 10).map((p) => `${p.name} (${p.reason})`).join("; ") + ".");
  if (r.warnings && r.warnings.length) lines.push("Note: " + r.warnings.join(" "));
  const sc = { mode, unit, kerf: r.kerf, trim: r.trim, summary: s, unplaced: r.unplaced || [], page };
  if (mode === "sheet") sc.sheets = r.sheets.slice(0, 50).map((sh) => ({ name: sh.name, w: sh.w, h: sh.h, util: sh.util, parts: sh.parts })); else sc.bars = r.bars.slice(0, 100);
  const fmt = ["svg", "csv", "none"].includes(a.format) ? a.format : "csv";
  if (fmt === "csv") { const csv = r.csv(); if (csv.length <= OUT_CAP) { lines.push("Cut list CSV:", fence("csv", csv)); sc.csv = csv; } }
  else if (fmt === "svg" && mode === "sheet" && r.sheets.length) {
    const svgs = []; let total = 0;
    for (let i = 0; i < Math.min(r.sheets.length, 6); i++) { const v = r.svg(i); if (total + v.length > OUT_CAP) break; total += v.length; svgs.push(v); }
    svgs.forEach((v, i) => lines.push(`Sheet ${i + 1} layout SVG:`, fence("svg", v))); sc.svgs = svgs;
    if (svgs.length < r.sheets.length) lines.push(`(${r.sheets.length - svgs.length} more sheet layouts on the page.)`);
  }
  lines.push("Layouts are guillotine (edge-to-edge cuts); measure your blade's real kerf. Visual layouts and cut order: " + page);
  return ok(lines.join("\n"), sc);
}

function jigsaw(a) {
  const unit = a.unit === "in" ? "in" : "mm", rows = Math.round(num(a.rows)), cols = Math.round(num(a.cols));
  if (!(rows >= 2 && rows <= 40 && cols >= 2 && cols <= 40)) return err("rows and cols must be whole numbers from 2 to 40.");
  const o = { rows, cols, unit, width: num(a.width) > 0 ? num(a.width) : unit === "in" ? 12 : 300, height: num(a.height) > 0 ? num(a.height) : unit === "in" ? 8 : 200,
    seed: Number.isFinite(num(a.seed)) ? Math.round(num(a.seed)) : 1 };
  if (num(a.tab) !== undefined) o.tab = num(a.tab);
  if (num(a.jitter) !== undefined) o.jitter = num(a.jitter);
  if (num(a.radius) !== undefined) o.radius = num(a.radius);
  const j = J.generate(o);
  if (!j || !j.ok) return err(errs(j, "Check the sizes."));
  const page = `${T}/jigsaw-puzzle-generator/`, u = unit;
  const lines = [`**${j.pieces}-piece jigsaw (${rows} × ${cols}) on a ${j.width} × ${j.height} ${u} board:** pieces about ${r2(j.cellW)} × ${r2(j.cellH)} ${u}, ${Math.round(j.cutLength)} ${u} of cutting, seed ${j.seed}.`];
  if (j.warnings && j.warnings.length) lines.push("Note: " + j.warnings.join(" "));
  const sc = { rows, cols, pieces: j.pieces, unit: u, width: j.width, height: j.height, cell_w: j.cellW, cell_h: j.cellH, cut_length: j.cutLength, seed: j.seed, tab: j.tab, jitter: j.jitter, radius: j.radius, warnings: j.warnings || [], page };
  const fmt = ["svg", "dxf", "none"].includes(a.format) ? a.format : "svg";
  if (fmt !== "none") {
    const f = fmt === "svg" ? j.svg() : j.dxf();
    if (f.length > OUT_CAP) lines.push(`The ${fmt.toUpperCase()} is ${Math.round(f.length / 1024)} KB: too big to return inline; use format svg, fewer pieces, or download it from the page.`);
    else { lines.push(fmt === "svg" ? "True-size SVG cut file (one path per edge):" : "DXF R12 cut file:", fence(fmt, f)); sc[fmt] = f; }
  }
  lines.push("Laser tip: cut the knobs first and the border last, and test the kerf on scrap. Preview over a photo: " + page);
  return ok(lines.join("\n"), sc);
}

function scaleTool(a) {
  const page = `${T}/architectural-scale-calculator/`;
  if (a.real !== undefined && a.drawing !== undefined && a.scale === undefined) {
    const unit = str(a.unit, 4) || "mm";
    const realMm = S.parseLength(str(a.real, 60), unit), drawMm = S.parseLength(str(a.drawing, 60), unit);
    if (!(realMm > 0) || !(drawMm > 0)) return err("real and drawing must be lengths, e.g. real \"10 m\", drawing \"200 mm\".");
    const f = S.findScale({ real: realMm, realUnit: "mm", drawing: drawMm, drawingUnit: "mm" });
    if (!f || !f.ok) return err(errs(f, "Could not work out the scale."));
    const lines = [`**The drawing is at about 1:${r2(f.ratio)}.**`, "Nearest standard scales: " + f.nearest.slice(0, 5).map((x) => `${x.label} (${x.errPct >= 0 ? "+" : ""}${r2(x.errPct)}%)`).join(", ") + "."];
    lines.push("Printable scale ruler: " + page);
    return ok(lines.join("\n"), { mode: "find", ratio: f.ratio, nearest: f.nearest.slice(0, 8), page });
  }
  if (a.value === undefined || a.scale === undefined) return err("Give value and scale (e.g. value \"27'-6\\\"\", scale \"1/4\\\"=1'-0\\\"\"), or real + drawing lengths to find the scale.");
  const o = { value: typeof a.value === "number" ? a.value : str(a.value, 60), scale: str(a.scale, 40), direction: a.direction === "toReal" ? "toReal" : "toDrawing" };
  if (a.unit) o.unit = str(a.unit, 4);
  else if (typeof o.value === "string") { const m = o.value.trim().match(/(?:^|[\d.\s])(mm|cm|m|yd)$/i); if (m) o.unit = m[1].toLowerCase(); }
  if (!o.unit && /^\s*[\d.]+\s*$/.test(String(o.value)) && /^\s*1\s*:/.test(o.scale)) o.unit = "mm";
  if (a.out_unit) o.outUnit = str(a.out_unit, 4);
  if (a.to_scale) o.toScale = str(a.to_scale, 40);
  const r = S.convert(o);
  if (!r || !r.ok) return err(errs(r, "Could not read the value or scale. Scales look like 1/4\"=1'-0\", 1\"=20' or 1:50."));
  const lines = [`**${r.inText} ${r.direction === "toDrawing" ? "real → on the drawing" : "on the drawing → real"} at ${r.scaleLabel}${/^1:/.test(r.scaleLabel) ? "" : ` (1:${r2(r.ratio)})`}: ${r.outText}${r.ftIn && !String(r.outText).includes(r.ftIn) ? ` (${r.ftIn})` : ""}**.`];
  if (r.rescaled) lines.push(`At ${r.rescaled.to} the same drawing measures ${r2(r.rescaled.mm)} mm (× ${r2(r.rescaled.factor)}).`);
  lines.push("Printable scale ruler and the full architect/engineer scale table: " + page);
  return ok(lines.join("\n"), { mode: "convert", direction: r.direction, ratio: r.ratio, scale: r.scaleLabel, family: r.family, mm_in: r.mmIn, mm_out: r.mmOut, out: r.out, out_unit: r.outUnit, out_text: r.outText, ft_in: r.ftIn || null, rescaled: r.rescaled || null, page });
}

const HANDLERS = { calc_quilt: quilt, calc_fabric_yardage: yardage, optimize_cut_list: cutList, make_jigsaw_puzzle: jigsaw, convert_drawing_scale: scaleTool };
const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools64Tool(name) { return NAMES.has(name); }
export async function callTools64Tool(name, a) {
  a = a && typeof a === "object" ? a : {};
  try {
    if (HANDLERS[name]) return HANDLERS[name](a);
  } catch (e) {
    return err(`${name} failed: ${str(e && e.message, 300)}`);
  }
  return err("Unknown tool: " + name);
}
